#!/usr/bin/env node
// Compares the Rust ipc-protocol enum variants against the TypeScript mirror.
// Reports any variants that are present in Rust but not TypeScript (or vice
// versa). Does NOT auto-edit types.ts — that is intentional, the diff is more
// reviewable than an autogenerated file when message shapes change.
//
// Run with `npm run sync-types`.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..", "..", "..");
const RUST = path.join(ROOT, "crates", "ipc-protocol", "src", "lib.rs");
const TS = path.join(ROOT, "crates", "ui", "src", "lib", "types.ts");

const rust = fs.readFileSync(RUST, "utf8");
const ts = fs.readFileSync(TS, "utf8");

const ENUM_RE = /pub enum (CoreMessage|UiCommand)\s*\{([\s\S]*?)\n\}/g;
const VARIANT_RE = /^\s{4}([A-Z][A-Za-z0-9_]*)/gm;

const rustVariants = { CoreMessage: new Set(), UiCommand: new Set() };
let match;
while ((match = ENUM_RE.exec(rust)) !== null) {
  const [, enumName, body] = match;
  let v;
  while ((v = VARIANT_RE.exec(body)) !== null) {
    const variant = v[1];
    rustVariants[enumName].add(toSnakeCase(variant));
  }
}

const tsTypes = { CoreMessage: extractTsTypes(ts, "CoreMessage"), UiCommand: extractTsTypes(ts, "UiCommand") };

let problems = 0;
for (const enumName of /** @type {const} */ (["CoreMessage", "UiCommand"])) {
  const r = rustVariants[enumName];
  const t = tsTypes[enumName];
  const missingInTs = [...r].filter((v) => !t.has(v));
  const extraInTs = [...t].filter((v) => !r.has(v));
  if (missingInTs.length || extraInTs.length) {
    problems += 1;
    console.error(`[${enumName}] mismatch:`);
    if (missingInTs.length) console.error(`  missing in TS: ${missingInTs.join(", ")}`);
    if (extraInTs.length) console.error(`  extra in TS  : ${extraInTs.join(", ")}`);
  } else {
    console.log(`[${enumName}] OK (${r.size} variants)`);
  }
}

if (problems > 0) {
  console.error(`\n${problems} mismatch(es). Update src/lib/types.ts to mirror crates/ipc-protocol/src/lib.rs.`);
  process.exit(1);
}

function toSnakeCase(s) {
  return s.replace(/([a-z0-9])([A-Z])/g, "$1_$2").replace(/([A-Z])([A-Z][a-z])/g, "$1_$2").toLowerCase();
}

function extractTsTypes(source, name) {
  const startMatch = new RegExp(`export type ${name}\\s*=`).exec(source);
  if (!startMatch) return new Set();
  const startIdx = startMatch.index + startMatch[0].length;
  const tail = source.slice(startIdx);
  const stop = tail.search(/^\s*export\s/m);
  const block = stop === -1 ? tail : tail.slice(0, stop);
  const out = new Set();
  const variantRe = /type:\s*"([a-z0-9_]+)"/g;
  let v;
  while ((v = variantRe.exec(block)) !== null) {
    out.add(v[1]);
  }
  return out;
}
